"use client"

import type { ComponentProps } from "react"
import { ContextMenu as ContextMenuPrimitive } from "@base-ui/react/context-menu"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./context-menu.css"

function withBase<State>(
  base: string,
  className?: string | ((state: State) => string | undefined)
) {
  return (state: State) =>
    cn(base, typeof className === "function" ? className(state) : className)
}

function CheckIcon(props: ComponentProps<"svg">) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="M20 6 9 17l-5-5" />
    </svg>
  )
}

function ChevronRightIcon(props: ComponentProps<"svg">) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="m9 18 6-6-6-6" />
    </svg>
  )
}

const contextMenuItemVariants = cva("np-context-menu-item", {
  variants: {
    variant: {
      default: "",
      destructive: "np-context-menu-destructive",
    },
  },
  defaultVariants: { variant: "default" },
})

/** Root of the menu. It has no element of its own. */
const ContextMenu = ContextMenuPrimitive.Root

/** Groups related items. Pair it with `ContextMenuLabel`. */
const ContextMenuGroup = ContextMenuPrimitive.Group

/** Groups radio items. Only one item can be checked. */
const ContextMenuRadioGroup = ContextMenuPrimitive.RadioGroup

/** Root of a submenu. Wraps a `ContextMenuSubTrigger` and a `ContextMenuSubContent`. */
const ContextMenuSub = ContextMenuPrimitive.SubmenuRoot

/** The area that opens the menu on right click or long press. */
function ContextMenuTrigger({
  className,
  ...props
}: ContextMenuPrimitive.Trigger.Props) {
  return (
    <ContextMenuPrimitive.Trigger
      data-slot="context-menu-trigger"
      className={withBase("np-context-menu-trigger", className)}
      {...props}
    />
  )
}

/** The menu. It is rendered in a portal and placed at the pointer. */
function ContextMenuContent({
  className,
  align = "start",
  alignOffset = 4,
  side = "right",
  sideOffset = 0,
  ...props
}: ContextMenuPrimitive.Popup.Props &
  Pick<
    ContextMenuPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  >) {
  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuPrimitive.Positioner
        className="np-context-menu-positioner"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <ContextMenuPrimitive.Popup
          data-slot="context-menu-content"
          className={withBase("np-context-menu-content", className)}
          {...props}
        />
      </ContextMenuPrimitive.Positioner>
    </ContextMenuPrimitive.Portal>
  )
}

/** The content of a submenu. It opens to the side of its trigger. */
function ContextMenuSubContent({
  className,
  side = "right",
  ...props
}: ComponentProps<typeof ContextMenuContent>) {
  return (
    <ContextMenuContent
      data-slot="context-menu-sub-content"
      className={withBase("np-context-menu-sub-content", className)}
      side={side}
      {...props}
    />
  )
}

/** The item that opens a submenu. It shows a chevron. */
function ContextMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: ContextMenuPrimitive.SubmenuTrigger.Props & {
  /** Indent the item so it lines up with items that have an indicator. */
  inset?: boolean
}) {
  return (
    <ContextMenuPrimitive.SubmenuTrigger
      data-slot="context-menu-sub-trigger"
      data-inset={inset ? "" : undefined}
      className={withBase("np-context-menu-sub-trigger", className)}
      {...props}
    >
      {children}
      <ChevronRightIcon className="np-context-menu-sub-indicator" />
    </ContextMenuPrimitive.SubmenuTrigger>
  )
}

/** An action. Closes the menu when it is chosen. */
function ContextMenuItem({
  className,
  inset,
  variant = "default",
  ...props
}: ContextMenuPrimitive.Item.Props & {
  /** Indent the item so it lines up with items that have an indicator. */
  inset?: boolean
  /**
   * Use `destructive` for an action that deletes or removes.
   * @default "default"
   */
  variant?: NonNullable<VariantProps<typeof contextMenuItemVariants>["variant"]>
}) {
  return (
    <ContextMenuPrimitive.Item
      data-slot="context-menu-item"
      data-inset={inset ? "" : undefined}
      data-variant={variant}
      className={withBase(contextMenuItemVariants({ variant }), className)}
      {...props}
    />
  )
}

/** A toggle item. It shows a check when it is checked. */
function ContextMenuCheckboxItem({
  className,
  children,
  inset,
  ...props
}: ContextMenuPrimitive.CheckboxItem.Props & {
  /** Indent the item so it lines up with items that have an indicator. */
  inset?: boolean
}) {
  return (
    <ContextMenuPrimitive.CheckboxItem
      data-slot="context-menu-checkbox-item"
      data-inset={inset ? "" : undefined}
      className={withBase("np-context-menu-checkbox-item", className)}
      {...props}
    >
      <span className="np-context-menu-item-indicator">
        <ContextMenuPrimitive.CheckboxItemIndicator>
          <CheckIcon />
        </ContextMenuPrimitive.CheckboxItemIndicator>
      </span>
      {children}
    </ContextMenuPrimitive.CheckboxItem>
  )
}

/** An exclusive choice inside a `ContextMenuRadioGroup`. */
function ContextMenuRadioItem({
  className,
  children,
  inset,
  ...props
}: ContextMenuPrimitive.RadioItem.Props & {
  /** Indent the item so it lines up with items that have an indicator. */
  inset?: boolean
}) {
  return (
    <ContextMenuPrimitive.RadioItem
      data-slot="context-menu-radio-item"
      data-inset={inset ? "" : undefined}
      className={withBase("np-context-menu-radio-item", className)}
      {...props}
    >
      <span className="np-context-menu-item-indicator">
        <ContextMenuPrimitive.RadioItemIndicator>
          <CheckIcon />
        </ContextMenuPrimitive.RadioItemIndicator>
      </span>
      {children}
    </ContextMenuPrimitive.RadioItem>
  )
}

/** A label for a `ContextMenuGroup`. */
function ContextMenuLabel({
  className,
  inset,
  ...props
}: ContextMenuPrimitive.GroupLabel.Props & {
  /** Indent the label so it lines up with items that have an indicator. */
  inset?: boolean
}) {
  return (
    <ContextMenuPrimitive.GroupLabel
      data-slot="context-menu-label"
      data-inset={inset ? "" : undefined}
      className={withBase("np-context-menu-label", className)}
      {...props}
    />
  )
}

/** A line between groups of items. */
function ContextMenuSeparator({
  className,
  ...props
}: ContextMenuPrimitive.Separator.Props) {
  return (
    <ContextMenuPrimitive.Separator
      data-slot="context-menu-separator"
      className={withBase("np-context-menu-separator", className)}
      {...props}
    />
  )
}

/** A keyboard hint at the end of an item, such as ⌘R. */
function ContextMenuShortcut({ className, ...props }: ComponentProps<"span">) {
  return (
    <span
      data-slot="context-menu-shortcut"
      className={cn("np-context-menu-shortcut", className)}
      {...props}
    />
  )
}

export {
  ContextMenu,
  ContextMenuCheckboxItem,
  ContextMenuContent,
  ContextMenuGroup,
  ContextMenuItem,
  ContextMenuLabel,
  ContextMenuRadioGroup,
  ContextMenuRadioItem,
  ContextMenuSeparator,
  ContextMenuShortcut,
  ContextMenuSub,
  ContextMenuSubContent,
  ContextMenuSubTrigger,
  ContextMenuTrigger,
  contextMenuItemVariants,
}

/* nepui - Context Menu */

.np-context-menu-trigger,
[data-np-context-menu-trigger] {
  -webkit-touch-callout: none;
}

.np-context-menu-positioner,
[data-np-context-menu-positioner] {
  isolation: isolate;
  z-index: var(--np-context-menu-z-index, 50);
}

.np-context-menu-content,
[data-np-context-menu-content],
.np-context-menu-sub-content,
[data-np-context-menu-sub-content] {
  --spacing: 0.25rem;
  --np-context-menu-min-width: calc(var(--spacing) * 36);
  --np-context-menu-padding: calc(var(--spacing) * 1);
  --np-context-menu-radius: var(--np-radius-lg);
  --np-context-menu-bg: var(--np-popover);
  --np-context-menu-fg: var(--np-popover-foreground);
  --np-context-menu-shadow: var(--np-shadow-md);
  --np-context-menu-ring: color-mix(
    in oklch,
    var(--np-foreground) 10%,
    transparent
  );
  --np-context-menu-duration: 100ms;
  --np-context-menu-slide-x: 0px;
  --np-context-menu-slide-y: 0px;

  box-sizing: border-box;
  position: relative;
  min-width: var(--np-context-menu-min-width);
  max-height: var(--available-height, none);
  margin: 0;
  padding: var(--np-context-menu-padding);
  overflow-x: hidden;
  overflow-y: auto;
  border-radius: var(--np-context-menu-radius);
  background-color: var(--np-context-menu-bg);
  color: var(--np-context-menu-fg);
  font-size: 0.875rem;
  line-height: 1.25rem;
  box-shadow:
    0 0 0 1px var(--np-context-menu-ring),
    var(--np-context-menu-shadow);
  outline: none;
  transform-origin: var(--transform-origin, top left);
}

.np-context-menu-sub-content,
[data-np-context-menu-sub-content] {
  --np-context-menu-min-width: calc(var(--spacing) * 24);
  --np-context-menu-shadow: var(--np-shadow-lg);
}

:is(
  .np-context-menu-content,
  [data-np-context-menu-content],
  .np-context-menu-sub-content,
  [data-np-context-menu-sub-content]
)[data-side="bottom"] {
  --np-context-menu-slide-y: calc(var(--spacing) * -2);
}

:is(
  .np-context-menu-content,
  [data-np-context-menu-content],
  .np-context-menu-sub-content,
  [data-np-context-menu-sub-content]
)[data-side="top"] {
  --np-context-menu-slide-y: calc(var(--spacing) * 2);
}

:is(
  .np-context-menu-content,
  [data-np-context-menu-content],
  .np-context-menu-sub-content,
  [data-np-context-menu-sub-content]
):is([data-side="inline-end"], [data-side="right"]) {
  --np-context-menu-slide-x: calc(var(--spacing) * -2);
}

:is(
  .np-context-menu-content,
  [data-np-context-menu-content],
  .np-context-menu-sub-content,
  [data-np-context-menu-sub-content]
):is([data-side="inline-start"], [data-side="left"]) {
  --np-context-menu-slide-x: calc(var(--spacing) * 2);
}

:is(
  .np-context-menu-content,
  [data-np-context-menu-content],
  .np-context-menu-sub-content,
  [data-np-context-menu-sub-content]
)[data-open] {
  animation: np-context-menu-in var(--np-context-menu-duration) ease;
}

:is(
  .np-context-menu-content,
  [data-np-context-menu-content],
  .np-context-menu-sub-content,
  [data-np-context-menu-sub-content]
)[data-closed] {
  animation: np-context-menu-out var(--np-context-menu-duration) ease forwards;
}

.np-context-menu-item,
[data-np-context-menu-item],
.np-context-menu-checkbox-item,
[data-np-context-menu-checkbox-item],
.np-context-menu-radio-item,
[data-np-context-menu-radio-item],
.np-context-menu-sub-trigger,
[data-np-context-menu-sub-trigger] {
  --np-context-menu-item-radius: var(--np-radius-md);
  --np-context-menu-item-icon-size: calc(var(--spacing) * 4);
  --np-context-menu-destructive-bg: color-mix(
    in oklch,
    var(--np-destructive) 10%,
    transparent
  );

  box-sizing: border-box;
  position: relative;
  display: flex;
  align-items: center;
  gap: calc(var(--spacing) * 1.5);
  width: 100%;
  min-height: calc(var(--spacing) * 8);
  margin: 0;
  padding: calc(var(--spacing) * 1) calc(var(--spacing) * 1.5);
  border: 0;
  border-radius: var(--np-context-menu-item-radius);
  background: transparent;
  color: inherit;
  font-family: inherit;
  font-size: 0.875rem;
  line-height: 1.25rem;
  text-align: start;
  cursor: default;
  outline: none;
  user-select: none;
}

:is(
  .np-context-menu-checkbox-item,
  [data-np-context-menu-checkbox-item],
  .np-context-menu-radio-item,
  [data-np-context-menu-radio-item]
) {
  padding-inline-end: calc(var(--spacing) * 8);
}

:is(
  .np-context-menu-item,
  [data-np-context-menu-item],
  .np-context-menu-checkbox-item,
  [data-np-context-menu-checkbox-item],
  .np-context-menu-radio-item,
  [data-np-context-menu-radio-item],
  .np-context-menu-sub-trigger,
  [data-np-context-menu-sub-trigger]
):is(.np-context-menu-inset, [data-inset]) {
  padding-inline-start: calc(var(--spacing) * 7);
}

:is(
  .np-context-menu-item,
  [data-np-context-menu-item],
  .np-context-menu-checkbox-item,
  [data-np-context-menu-checkbox-item],
  .np-context-menu-radio-item,
  [data-np-context-menu-radio-item],
  .np-context-menu-sub-trigger,
  [data-np-context-menu-sub-trigger]
):is(:focus, [data-highlighted], [data-popup-open], [aria-expanded="true"]) {
  background-color: var(--np-accent);
  color: var(--np-accent-foreground);
}

:is(
    .np-context-menu-item,
    [data-np-context-menu-item],
    .np-context-menu-checkbox-item,
    [data-np-context-menu-checkbox-item],
    .np-context-menu-radio-item,
    [data-np-context-menu-radio-item],
    .np-context-menu-sub-trigger,
    [data-np-context-menu-sub-trigger]
  ):is(
    :focus,
    [data-highlighted],
    [data-popup-open],
    [aria-expanded="true"]
  ):not(:is(.np-context-menu-destructive, [data-variant="destructive"]))
  * {
  color: var(--np-accent-foreground);
}

:is(
  .np-context-menu-item,
  [data-np-context-menu-item],
  .np-context-menu-checkbox-item,
  [data-np-context-menu-checkbox-item],
  .np-context-menu-radio-item,
  [data-np-context-menu-radio-item],
  .np-context-menu-sub-trigger,
  [data-np-context-menu-sub-trigger]
):is(.np-context-menu-destructive, [data-variant="destructive"]) {
  color: var(--np-destructive);
}

:is(
    .np-context-menu-item,
    [data-np-context-menu-item],
    .np-context-menu-checkbox-item,
    [data-np-context-menu-checkbox-item],
    .np-context-menu-radio-item,
    [data-np-context-menu-radio-item],
    .np-context-menu-sub-trigger,
    [data-np-context-menu-sub-trigger]
  ):is(.np-context-menu-destructive, [data-variant="destructive"])
  svg {
  color: var(--np-destructive);
}

:is(
    .np-context-menu-item,
    [data-np-context-menu-item],
    .np-context-menu-checkbox-item,
    [data-np-context-menu-checkbox-item],
    .np-context-menu-radio-item,
    [data-np-context-menu-radio-item],
    .np-context-menu-sub-trigger,
    [data-np-context-menu-sub-trigger]
  ):is(.np-context-menu-destructive, [data-variant="destructive"]):is(
    :focus,
    [data-highlighted]
  ) {
  background-color: var(--np-context-menu-destructive-bg);
  color: var(--np-destructive);
}

:is(
  .np-context-menu-item,
  [data-np-context-menu-item],
  .np-context-menu-checkbox-item,
  [data-np-context-menu-checkbox-item],
  .np-context-menu-radio-item,
  [data-np-context-menu-radio-item],
  .np-context-menu-sub-trigger,
  [data-np-context-menu-sub-trigger]
):is([data-disabled], [aria-disabled="true"]) {
  opacity: 0.5;
  pointer-events: none;
}

:is(
    .np-context-menu-item,
    [data-np-context-menu-item],
    .np-context-menu-checkbox-item,
    [data-np-context-menu-checkbox-item],
    .np-context-menu-radio-item,
    [data-np-context-menu-radio-item],
    .np-context-menu-sub-trigger,
    [data-np-context-menu-sub-trigger]
  )
  svg {
  flex-shrink: 0;
  pointer-events: none;
}

:is(
    .np-context-menu-item,
    [data-np-context-menu-item],
    .np-context-menu-checkbox-item,
    [data-np-context-menu-checkbox-item],
    .np-context-menu-radio-item,
    [data-np-context-menu-radio-item],
    .np-context-menu-sub-trigger,
    [data-np-context-menu-sub-trigger]
  )
  svg:not([class*="size-"]) {
  width: var(--np-context-menu-item-icon-size);
  height: var(--np-context-menu-item-icon-size);
}

.np-context-menu-item-indicator,
[data-np-context-menu-item-indicator] {
  position: absolute;
  inset-inline-end: calc(var(--spacing) * 2);
  display: flex;
  align-items: center;
  justify-content: center;
  width: calc(var(--spacing) * 4);
  height: calc(var(--spacing) * 4);
  pointer-events: none;
}

:is(
    .np-context-menu-checkbox-item,
    [data-np-context-menu-checkbox-item],
    .np-context-menu-radio-item,
    [data-np-context-menu-radio-item]
  )[aria-checked="false"]
  :is(.np-context-menu-item-indicator, [data-np-context-menu-item-indicator]) {
  display: none;
}

.np-context-menu-sub-indicator,
[data-np-context-menu-sub-indicator] {
  margin-inline-start: auto;
}

:is(.np-context-menu-sub-indicator, [data-np-context-menu-sub-indicator]):dir(
  rtl
) {
  transform: scaleX(-1);
}

.np-context-menu-sub,
[data-np-context-menu-sub] {
  position: relative;
}

.np-context-menu-label,
[data-np-context-menu-label] {
  padding: calc(var(--spacing) * 1) calc(var(--spacing) * 1.5);
  color: var(--np-muted-foreground);
  font-size: 0.75rem;
  font-weight: 500;
  line-height: 1.25rem;
}

:is(.np-context-menu-label, [data-np-context-menu-label]):is(
  .np-context-menu-inset,
  [data-inset]
) {
  padding-inline-start: calc(var(--spacing) * 7);
}

.np-context-menu-separator,
[data-np-context-menu-separator] {
  height: 1px;
  margin-block: calc(var(--spacing) * 1);
  margin-inline: calc(var(--spacing) * -1);
  background-color: var(--np-border);
  pointer-events: none;
}

.np-context-menu-shortcut,
[data-np-context-menu-shortcut] {
  margin-inline-start: auto;
  color: var(--np-muted-foreground);
  font-size: 0.75rem;
  letter-spacing: 0.1em;
}

:is(.dark, [data-theme="dark"])
  :is(
    .np-context-menu-item,
    [data-np-context-menu-item],
    .np-context-menu-checkbox-item,
    [data-np-context-menu-checkbox-item],
    .np-context-menu-radio-item,
    [data-np-context-menu-radio-item],
    .np-context-menu-sub-trigger,
    [data-np-context-menu-sub-trigger]
  ) {
  --np-context-menu-destructive-bg: color-mix(
    in oklch,
    var(--np-destructive) 20%,
    transparent
  );
}

@media (prefers-color-scheme: dark) {
  :root:not(.light, [data-theme="light"])
    :is(
      .np-context-menu-item,
      [data-np-context-menu-item],
      .np-context-menu-checkbox-item,
      [data-np-context-menu-checkbox-item],
      .np-context-menu-radio-item,
      [data-np-context-menu-radio-item],
      .np-context-menu-sub-trigger,
      [data-np-context-menu-sub-trigger]
    ) {
    --np-context-menu-destructive-bg: color-mix(
      in oklch,
      var(--np-destructive) 20%,
      transparent
    );
  }
}

@keyframes np-context-menu-in {
  from {
    opacity: 0;
    transform: translate(
        var(--np-context-menu-slide-x),
        var(--np-context-menu-slide-y)
      )
      scale(0.95);
  }
}

@keyframes np-context-menu-out {
  to {
    opacity: 0;
    transform: scale(0.95);
  }
}

@media (prefers-reduced-motion: reduce) {
  :is(
    .np-context-menu-content,
    [data-np-context-menu-content],
    .np-context-menu-sub-content,
    [data-np-context-menu-sub-content]
  )[data-open],
  :is(
    .np-context-menu-content,
    [data-np-context-menu-content],
    .np-context-menu-sub-content,
    [data-np-context-menu-sub-content]
  )[data-closed] {
    animation: none;
  }
}
